    pub(super) fn scan_progress(kind: ScanKind) {
        let cb = ACTIVE_PROBE.with(|slot| slot.borrow().as_ref().and_then(|p| p.scan_cb.clone()));
        if let Some(cb) = cb {
            cb(ScanEvent::Progress(kind));
        }
    }

